/**
 * One thing to act on.
 *
 * `id` is stable across calls; `kind` names the situation. `title`,
 * `description` and `primary_action` are English (the old web);
 * `message_key` + `message_params` are the translatable form.
 */
export type WorkItem = {
    activity_id: ActivityId;
    activity_title: string;
    allowed_actions: Array<string>;
    /**
     * Teacher items: the file-submission attempt under review (absent otherwise).
     */
    attempt_id?: FileAttemptId;
    course_id: CourseId;
    course_title: string;
    created_at_unix: UnixTime | null;
    description: string;
    due_at_unix: UnixTime | null;
    /**
     * Client route for the primary action.
     */
    href: string;
    id: string;
    kind: WorkKind;
    /**
     * Teacher items: the learner's display name, else username (absent otherwise).
     */
    learner_name?: string;
    /**
     * Always present on this server (optional in the schema so earlier
     * clients' fixtures stay valid).
     */
    message_key?: WorkMessageKey;
    /**
     * Always present, like `message_key`.
     */
    message_params?: WorkMessageParams;
    primary_action: string;
    priority: WorkPriority;
    role: WorkRole;
    status: WorkStatus;
    /**
     * Teacher items: the assessment submission under review (absent otherwise).
     */
    submission_id?: SubmissionId;
    title: string;
};

/**
 * The situation an item names.
 */
export type WorkKind = 'in_progress' | 'overdue' | 'waiting_for_grade' | 'returned_for_revision' | 'feedback_released' | 'needs_grading' | 'sla_breach' | 'awaiting_release';

/**
 * The message an item shows: the client renders `work_<key>_title`,
 * `_description` and `_action` with [`WorkMessageParams`] (the English
 * `title` / `description` / `primary_action` stay for the old web).
 */
export type WorkMessageKey = 'revise' | 'awaiting_feedback' | 'review_feedback' | 'continue' | 'grade' | 'release';

/**
 * Placeholders of a [`WorkMessageKey`].
 */
export type WorkMessageParams = {
    activity: string;
    course: string;
    /**
     * The learner's display name (teacher items).
     */
    learner: string | null;
};

export type WorkPriority = 'critical' | 'high' | 'normal' | 'low';

/**
 * One page; `total` counts the whole (filtered) queue before paging.
 */
export type WorkQueue = {
    items: Array<WorkItem>;
    next_cursor: string | null;
    total: number;
};

/**
 * Which inbox to assemble.
 */
export type WorkRole = 'learner' | 'teacher';

/**
 * `GET /work` order (INBOX-DATA).
 */
export type WorkSort = 'priority' | 'due' | 'oldest' | 'newest';

/**
 * Product-level work state shown to the learner.
 */
export type WorkState = 'not_started' | 'in_progress' | 'submitted' | 'needs_grading' | 'graded_hidden' | 'returned' | 'passed' | 'failed' | 'complete' | 'locked';

/**
 * The work's grading status.
 */
export type WorkStatus = 'in_progress' | 'needs_grading' | 'returned' | 'published' | 'graded_hidden';

export type WorkloadAgingBuckets = {
    d1_3: number;
    d3_7: number;
    d7_plus: number;
    h0_24: number;
};

/**
 * XP granted to the recipient (S-13).
 */
export type XpAwarded = {
    amount: number;
    level: number;
    /**
     * Free-text reason (admin awards); null for automatic sources.
     */
    reason: string | null;
    source: XpSource;
    /**
     * The new total and level after this award.
     */
    total_xp: number;
    transaction_id: XpTransactionId;
};

/**
 * One page of the caller's XP history, newest first.
 */
export type XpHistoryPage = {
    items: Array<Transaction>;
    next_cursor: XpTransactionId | null;
};

export type XpNotificationSettings = {
    xp_gain: boolean | null;
};

/**
 * Why XP was granted (legacy `XPSource`).
 */
export type XpSource = 'activity_completion' | 'course_completion' | 'login_bonus' | 'quiz_completion' | 'exam_completion' | 'streak_bonus' | 'admin_award' | 'code_challenge_completion' | 'code_challenge_perfect' | 'code_challenge_first_solve';

export type XpTransactionId = string;

